        print("REVIEWS")
        for r in con.execute("select * from reviews"):
            print(dict(r))
    elif cmd == "page":
        print(get())
    elif cmd == "post":
        print(post(sys.argv[4]))
    elif cmd == "q":
        print(card_q(get()))
