import sqlite3, subprocess, time, urllib.request, urllib.error, re, os, sys, json, shutil

EXE = "/workspace/executable"

def make_coll(path, n=1):
    if os.path.exists(path): shutil.rmtree(path)
    os.makedirs(path)
    with open(os.path.join(path, "deck.md"), "w") as f:
        for i in range(n):
            f.write(f"Q: question {i}\nA: answer {i}\n\n")

def start(path, port):
    p = subprocess.Popen([EXE, "drill", "--port", str(port), "--open-browser", "false"],
                         cwd=path, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    for _ in range(50):
        try:
            urllib.request.urlopen(f"http://127.0.0.1:{port}/", timeout=1); break
        except Exception: time.sleep(0.1)
    return p

def post(port, action):
    req = urllib.request.Request(f"http://127.0.0.1:{port}/", data=f"action={action}".encode())
    try:
        return urllib.request.urlopen(req, timeout=5).read().decode()
    except urllib.error.HTTPError as e:
        return f"HTTP {e.code}"

def getq(port):
    html = urllib.request.urlopen(f"http://127.0.0.1:{port}/", timeout=5).read().decode()
    m = re.search(r'<div class="question rich-text">(.*?)</div>', html, re.S)
    return m.group(1).strip() if m else None

def grade(port, g):
    post(port, "Reveal"); return post(port, g)

def dbrows(path):
    con = sqlite3.connect(os.path.join(path, "hashcards.db")); con.row_factory = sqlite3.Row
    cards = [dict(r) for r in con.execute("select * from cards")]
    reviews = [dict(r) for r in con.execute("select * from reviews order by review_id")]
    sessions = [dict(r) for r in con.execute("select * from sessions")]
    con.close()
    return cards, reviews, sessions

def set_card(path, **kw):
    con = sqlite3.connect(os.path.join(path, "hashcards.db"))
    sets = ", ".join(f"{k}=?" for k in kw)
    con.execute(f"update cards set {sets}", tuple(kw.values()))
    con.commit(); con.close()

def run_sequence(path, port, steps, stop_wait=0.3):
    """steps: list of ('grade', G) or ('edit', dict) ; between edits we restart the server."""
    p = start(path, port)
    out = []
    try:
        for step in steps:
            if step[0] == "grade":
                q = getq(port)
                if q is None:
                    out.append(("NOCARD", None)); continue
                grade(port, step[1]); out.append((q, step[1]))
            elif step[0] == "end":
                post(port, "End")
            elif step[0] == "restart":
                post(port, "End"); p.terminate(); p.wait()
                if step[1]: set_card(path, **step[1])
                p = start(path, port)
        post(port, "End")
    finally:
        p.terminate(); p.wait()
    return out

if __name__ == "__main__":
    pass
